<?php declare(strict_types=1); $e=static fn(mixed $v): string => htmlspecialchars((string)$v, ENT_QUOTES, "UTF-8"); ?><?php $data=$record??$old??[]; ?><div class="card"><div class="form-grid"><div class="form-group"><label>Provider</label><select name="provider_id"><option value="">Not assigned</option><?php foreach($providers as $p): ?><option value="<?= (int)$p['id'] ?>" <?= (string)($data['provider_id']??'')===(string)$p['id']?'selected':'' ?>><?= $e($p['business_name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Vehicle / Equipment</label><select name="vehicle_id"><option value="">Not assigned</option><?php foreach($vehicles as $v): ?><option value="<?= (int)$v['id'] ?>" <?= (string)($data['vehicle_id']??'')===(string)$v['id']?'selected':'' ?>><?= $e($v['name'].' — '.$v['provider_name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Customer Name <span class="required">*</span></label><input name="customer_name" required value="<?= $e($data['customer_name'] ?? '') ?>"></div><div class="form-group"><label>Customer Phone <span class="required">*</span></label><input name="customer_phone" required value="<?= $e($data['customer_phone'] ?? '') ?>"></div><div class="form-group full-width"><label>Purpose</label><input name="purpose" placeholder="Construction, shifting, agriculture, water delivery..." value="<?= $e($data['purpose'] ?? '') ?>"></div><div class="form-group full-width"><label>Pickup / Work Location <span class="required">*</span></label><input name="pickup_address" required value="<?= $e($data['pickup_address'] ?? '') ?>"></div><div class="form-group"><label>Pickup Latitude</label><input name="pickup_lat" value="<?= $e($data['pickup_lat'] ?? '') ?>"></div><div class="form-group"><label>Pickup Longitude</label><input name="pickup_lng" value="<?= $e($data['pickup_lng'] ?? '') ?>"></div><div class="form-group full-width"><label>Destination (if applicable)</label><input name="destination_address" value="<?= $e($data['destination_address'] ?? '') ?>"></div><div class="form-group"><label>Start</label><input type="datetime-local" name="start_at" value="<?= $e($data['start_at'] ?? '') ?>"></div><div class="form-group"><label>End</label><input type="datetime-local" name="end_at" value="<?= $e($data['end_at'] ?? '') ?>"></div><div class="form-group"><label>Duration</label><input name="duration_text" placeholder="e.g. 2 days" value="<?= $e($data['duration_text'] ?? '') ?>"></div><div class="form-group"><label><input type="checkbox" name="operator_required" value="1" <?= !empty($data['operator_required'])?'checked':'' ?>> Operator required</label></div><div class="form-group"><label>Status</label><select name="status"><?php foreach(['REQUESTED','CONTACTING','QUOTED','CONFIRMED','IN_PROGRESS','COMPLETED','CANCELLED','REJECTED'] as $v): ?><option value="<?= $v ?>" <?= ($data['status']??'REQUESTED')===$v?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Quoted Amount (₹)</label><input type="number" step="0.01" min="0" name="quoted_amount" value="<?= $e($data['quoted_amount'] ?? '') ?>"></div><div class="form-group"><label>Final Amount (₹)</label><input type="number" step="0.01" min="0" name="final_amount" value="<?= $e($data['final_amount'] ?? '') ?>"></div><div class="form-group full-width"><label>Customer Notes</label><textarea name="customer_notes" rows="3"><?= $e($data['customer_notes'] ?? '') ?></textarea></div><div class="form-group full-width"><label>Admin Notes</label><textarea name="admin_notes" rows="4"><?= $e($data['admin_notes'] ?? '') ?></textarea></div></div></div>
